import hashlib
import json

DATEN = ["Affe", "Banane", "Zitrone", "Apfel", "Birne"]
def kanon(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=False, separators=(",", ":"))
PIN = hashlib.sha256(kanon(DATEN).encode("utf-8")).hexdigest()
CFG = {"daten": DATEN, "min_laenge": 5, "pins": {"daten": PIN}}
erg = run_pipeline(CFG)
__check('status ok', erg["status"] == "ok")
__check('bericht anzahl', erg["bericht"]["anzahl"] == 4)
__check('bericht anfangsbuchstaben', erg["bericht"]["anfangsbuchstaben"] == {"a": 1, "b": 2, "z": 1})
__check('digest stimmt', erg["digest"] == hashlib.sha256(kanon(erg["bericht"]).encode("utf-8")).hexdigest())
__check('doppellauf identisch', run_pipeline(CFG) == erg)
TAMPER = {"daten": ["Affe", "Banane", "Zitrone", "Apfel", "Kirsche"], "min_laenge": 5, "pins": {"daten": PIN}}
try:
    run_pipeline(TAMPER)
    __check('tamper erkannt', False)
except AssertionError as e:
    __check('tamper erkannt', "freeze verletzt" in str(e))

