import hashlib
import json


def kanon(obj):
    return json.dumps(obj, sort_keys=True, ensure_ascii=False, separators=(",", ":"))


def repro_check(readme, laeufe, phrasen):
    digests = [hashlib.sha256(kanon(lauf).encode("utf-8")).hexdigest() for lauf in laeufe]
    identisch = all(d == digests[0] for d in digests) if digests else True
    t = readme.lower()
    overclaims = sorted(p for p in phrasen if p in t)
    verdict = "angenommen" if identisch and not overclaims else "abgelehnt"
    return {"digest_identisch": identisch, "digests": digests, "overclaims": overclaims, "verdict": verdict}

# Kanonik gleicht Schluesselreihenfolge aus; Verdikt kombiniert Reproduktion und ehrlichen Text

